Definition r90a_bits_exit (sp gp tp t1 s0 s1 a2 a3 a4 a5 a6 s3 s4 s7 s8 s9 s10 s11 t4 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (D nD TE : Z) : machine_state -> Prop :=
  fun ms' => exists (a1' s2' t3' t6' : word) (m' : mem),
    ms' = MS (mkR (Z_to_bv 64 0) sp gp tp (Z_to_bv 64 32) t1 (Z_to_bv 64 67108865) s0 s1 (Z_to_bv 64 TE) a1' a2 a3 a4 a5 a6 (Z_to_bv 64 1)
                  s2' s3 s4 (Z_to_bv 64 32) (Z_to_bv 64 TE) s7 s8 s9 s10 s11 t3' t4 (Z_to_bv 64 0) t6')
             F (Z_to_bv 64 r90a_wn) fc None m' (seg_rom asegs)
    /\ munch [(D, D + nD)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

Lemma r90a_bits : forall (n : nat) (k : Z)
    (sp gp tp t1 s0 s1 a2 a3 a4 a5 s3 s4 s7 s8 s9 t4 a1 s2 t3 t6 : word) F fc (m : mem) (D nD wpld T0 A7 A6 K T4 : Z),
