(* [comment removed for export] *)
Definition r90a_words_exit (sp gp tp s0 s1 a2 a3 a4 a6 s3 s4 s7 s8 s9 s10 s11 t4 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (D nD NW TE : Z) : machine_state -> Prop :=
  fun ms' => exists (a1' a5' s2' s5' s6' t3' t5' t6' : word) (m' : mem),
    ms' = MS (mkR (Z_to_bv 64 0) sp gp tp (Z_to_bv 64 32) (Z_to_bv 64 NW) (Z_to_bv 64 67108865) s0 s1 (Z_to_bv 64 TE) a1' a2 a3 a4 a5' a6 (Z_to_bv 64 1)
                  s2' s3 s4 s5' s6' s7 s8 s9 s10 s11 t3' t4 t5' t6')
             F (Z_to_bv 64 r90a_re) fc None m' (seg_rom asegs)
    /\ munch [(D, D + nD)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

Lemma r90a_words : forall (n : nat) (jw : Z)
    (sp gp tp s0 a2 a3 a4 s4 s7 s8 a1 a5 s2 s5 s6 t3 t5 t6 : word) F fc (m : mem) (D nD S nS wpld L A7 NW JW T4 A6 S1 : Z),
  Z.of_nat n = NW - jw -> 0 <= jw < NW -> NW <= 625 -> JW = jw -> T4 = D + 128 * wpld * jw -> A6 = 4 * wpld ->
  1 <= wpld <= 626 -> 0 < D -> D mod 4 = 0 -> D + nD <= 2^47 -> (D + nD <= 0x7fff7000 \/ 0x10007fff8000 <= D) ->
  A7 mod 4 = 0 -> 0 <= A7 -> A7 + 4 <= 4 * wpld -> 128 * wpld * NW <= nD ->
  0 < S -> S mod 4 = 0 -> S + nS <= 2^47 -> L mod 4 = 0 -> S <= L -> L + 4 * NW <= S + nS ->
  0 <= S1 -> S1 mod 8 = 0 -> S1 + 112 <= 2^47 -> (S1 + 112 <= D \/ D + nD <= S1 + 96) ->
  rw_cells asegs m (S1 + 96) [C8 (Z_to_bv 64 (128 * wpld))] -> rw_cells asegs m (S1 + 104) [C8 (Z_to_bv 64 0)] ->
  wr_at asegs m D nD -> acc asegs m D nD -> wr_at asegs m S nS -> acc asegs m S nS -> mem_inv asegs m ->
  evt asegs (r90a_words_exit sp gp tp s0 (Z_to_bv 64 S1) a2 a3 a4 (Z_to_bv 64 A6) (Z_to_bv 64 S) s4 s7 s8 (Z_to_bv 64 L) (Z_to_bv 64 A7) (Z_to_bv 64 2147450880) (Z_to_bv 64 NW)
               F fc m D nD NW (D + 128 * wpld * NW))
    (MS (mkR (Z_to_bv 64 0) sp gp tp (Z_to_bv 64 32) (Z_to_bv 64 JW) (Z_to_bv 64 67108865) s0 (Z_to_bv 64 S1) (Z_to_bv 64 T4) a1 a2 a3 a4 a5 (Z_to_bv 64 A6) (Z_to_bv 64 1)
             s2 (Z_to_bv 64 S) s4 s5 s6 s7 s8 (Z_to_bv 64 L) (Z_to_bv 64 A7) (Z_to_bv 64 2147450880) t3 (Z_to_bv 64 NW) t5 t6)
