(* [comment removed for export] *)
Definition r90B_rows_exit (sp gp tp s0 s1 s3 s4 s7 s8 s11 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) (D nD : Z) : machine_state -> Prop :=
  fun ms' => exists (ra' t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' s2' s5' s6' s9' s10' t3' t4' t5' t6' : word) (m' : mem),
    ms' = MS (mkR ra' sp gp tp t0' t1' t2' s0 s1 a0' a1' a2' a3' a4' a5' a6' a7' s2' s3 s4 s5' s6' s7 s8 s9' s10' s11 t3' t4' t5' t6')
             F (Z_to_bv 64 r90_dn) fc None m' (seg_rom asegs)
    /\ munch [(D, D + nD)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

Lemma r90a_rows : forall (n : nat) (i : Z)
    (sp gp tp s0 ra a1 a4 a5 s2 s5 s6 s9 s10 t1 t3 t5 t6 : word) F fc (m : mem) (D nD S nS wpld wpls WD WS NW F32 F48 S1 IR : Z),
  Z.of_nat n = WD - i -> 0 <= i < WD -> IR = i -> 0 <= S1 -> F48 = F32 + 16 ->
  1 <= WD <= 20000 -> 1 <= WS <= 20000 -> NW = WS / 32 -> wpld = (WD + 31) / 32 -> wpls = (WS + 31) / 32 -> nD = 4 * (wpld * WS) -> nS = 4 * (wpls * WD) ->
  0 < D -> D mod 4 = 0 -> D + nD <= 2^47 -> (D + nD <= 0x7fff7000 \/ 0x10007fff8000 <= D) ->
  0 < S -> S mod 4 = 0 -> S + nS <= 2^47 ->
  0 < F32 -> F32 mod 4 = 0 -> F32 + 20 <= 2^47 -> (F32 + 20 <= D \/ D + nD <= F32) -> (F32 + 20 <= 0x7fff7000 \/ 0x10007fff8000 <= F32) ->
  S1 mod 8 = 0 -> S1 + 128 <= 2^47 -> (S1 + 128 <= D \/ D + nD <= S1 + 80) ->
  rw_cells asegs m F32 [C4 (Z_to_bv 64 WD)] -> rw_cells asegs m F48 [C4 (Z_to_bv 64 WS)] ->
  rw_cells asegs m (S1 + 80) [C8 (Z_to_bv 64 WS)] -> rw_cells asegs m (S1 + 88) [C8 (Z_to_bv 64 (32 * NW))] ->
  rw_cells asegs m (S1 + 96) [C8 (Z_to_bv 64 (128 * wpld))] -> rw_cells asegs m (S1 + 104) [C8 (Z_to_bv 64 0)] ->
  rw_cells asegs m (S1 + 112) [C8 (Z_to_bv 64 wpld)] -> rw_cells asegs m (S1 + 120) [C8 (Z_to_bv 64 D)] ->
  wr_at asegs m D nD -> acc asegs m D nD -> wr_at asegs m S nS -> acc asegs m S nS -> mem_inv asegs m ->
  evt asegs (r90B_rows_exit sp gp tp s0 (Z_to_bv 64 S1) (Z_to_bv 64 S) (Z_to_bv 64 F32) (Z_to_bv 64 F48) (Z_to_bv 64 wpls) (Z_to_bv 64 2147450880) F fc m D nD)
    (MS (mkR ra sp gp tp (Z_to_bv 64 32) t1 (Z_to_bv 64 67108865) s0 (Z_to_bv 64 S1) (Z_to_bv 64 WD) a1 (Z_to_bv 64 IR) (Z_to_bv 64 IR) a4 a5
             (Z_to_bv 64 (4 * wpld)) (Z_to_bv 64 1) s2 (Z_to_bv 64 S) (Z_to_bv 64 F32) s5 s6 (Z_to_bv 64 F48) (Z_to_bv 64 wpls) s9 s10
             (Z_to_bv 64 2147450880) t3 (Z_to_bv 64 NW) t5 t6)
        F (Z_to_bv 64 r90a_hd) fc None m (seg_rom asegs)).
